const from='hyder@exampleabc.com';
const to='hakpilot@gmail.com';
const originalThreadId='1a17a3419cc3fa7b';
const originalMessageId='<CAEkxTPRF1zdBrGRSB5iYJfOqmpn7j950QTMKfAO_m=GLH6i7_Q@mail.gmail.com>';
if(from!=='hyder@exampleabc.com'||to!=='hakpilot@gmail.com'||originalThreadId!=='1a17a3419cc3fa7b')throw Error('QA12 verified sender/recipient/thread mismatch');
