 'From: Hyder Khan <'+from+'>',
 'To: '+to,
 'Subject: '+subject,
 'In-Reply-To: '+originalMessageId,
 'References: '+originalMessageId,
 'MIME-Version: 1.0',
 'Content-Type: text/plain; charset=UTF-8',
 'Content-Transfer-Encoding: 8bit',
 '',
 content
